import {KEY,seed,DEFAULT_CONTENT} from './seed.js';
import {money,dateLabel,clinicNow,transaction,uid,changeBooking,changeOrder,whatsappLink,bookingText,orderText,validateState,replaceData,validDate,validImage,slots,previousBackup} from './store.js';
import {e,icon,status,statusLabel,field,area,selectField,empty,modal,error,toast,submit,uploadImage,download} from './ui.js';
const tabs=[['overview','Visão geral','grid'],['agenda','Agendamentos','calendar'],['availability','Disponibilidade','clock'],['services','Tratamentos','foot'],['products','Produtos','bag'],['orders','Pedidos','box'],['customers','Clientes','users'],['content','Conteúdo e marca','edit'],['notifications','Notificações','bell'],['messages','Mensagens','mail'],['backup','Backup e dados','download']];
const titles=Object.fromEntries(tabs.map(([id,t])=>[id,t]));
const descriptions={overview:'Um olhar sobre seus atendimentos e sua loja.',agenda:'Todos os agendamentos, do site e do WhatsApp, em uma só agenda.',availability:'Defina quando você está disponível para cuidar dos seus clientes.',services:'Organize os tratamentos que aparecem no seu site.',products:'Cuide da sua seleção de produtos e do estoque.',orders:'Acompanhe seus pedidos, pagamentos e entregas.',customers:'Contatos e histórico de quem confia no seu cuidado.',content:'Seu site, do seu jeito. Edite os textos, imagens e a identidade.',notifications:'Novos agendamentos, pedidos e mensagens.',messages:'Conversas que começaram pelo formulário de contato.',backup:'Guarde uma cópia dos seus dados e restaure quando precisar.'};
const currentTab=()=>{const id=location.hash.split('/')[2]||'overview';return titles[id]?id:'overview';};
let filters={agendaDate:'',agendaStatus:'all',agendaSource:'all',ordersStatus:'all',customerQuery:''};
let contentGroup='hero';
export function renderAdmin(ctx){const d=ctx.getData(),tab=currentTab(),unread=d.notifications.filter(n=>!n.read).length;let body;
  switch(tab){case 'overview':body=overview(d);break;case 'agenda':body=agenda(d);break;case 'availability':body=availability(d);break;case 'services':body=catalog(d,'services');break;case 'products':body=catalog(d,'products');break;case 'orders':body=orders(d);break;case 'customers':body=customers(d);break;case 'content':body=content(d);break;case 'notifications':body=notifications(d);break;case 'messages':body=messages(d);break;default:body=backup(ctx);}
  return `<div class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="#/"><img src="${e(d.content.logo||'assets/logo.jpeg')}" alt="Logo ${e(d.content.brand)}"><div><div class="brand-name">${e(d.content.brand)}</div><small>ÁREA DA PROFISSIONAL</small></div></a><div class="sidebar-label">SEU CONSULTÓRIO</div><nav aria-label="Painel administrativo">${tabs.map(([id,title,ico])=>`<a class="${tab===id?'active':''}" href="#/admin/${id}" ${tab===id?'aria-current="page"':''}>${icon(ico)}<span>${title}</span>${id==='notifications'&&unread?`<b class="sidebar-count">${unread}</b>`:''}</a>`).join('')}</nav><a class="sidebar-site" href="#/">${icon('eye')} Ver meu site</a><div class="sidebar-note">${icon('lock')} Acesso autenticado<br><small>Dados compartilhados no servidor.</small><button class="btn secondary small" data-logout>Sair do painel</button></div></aside><div class="admin-main"><header class="admin-top"><span>Meu consultório <span class="muted">/ ${titles[tab]}</span></span><div class="flex"><a class="icon-btn" href="#/admin/notifications" aria-label="${unread} notificações não lidas">${icon('bell')}${unread?`<span class="count">${unread}</span>`:''}</a><div class="avatar">${e((d.content.brand||'B').slice(0,1))}</div></div></header><main id="main" class="admin-content"><div class="admin-heading"><div><div class="eyebrow">PAINEL DE GESTÃO</div><h1>${titles[tab]}</h1><p>${descriptions[tab]}</p></div>${['overview','agenda'].includes(tab)?'<button class="btn primary" data-manual>'+icon('plus')+' Agendamento WhatsApp</button>':tab==='services'?'<button class="btn primary" data-new="services">'+icon('plus')+' Novo tratamento</button>':tab==='products'?'<button class="btn primary" data-new="products">'+icon('plus')+' Novo produto</button>':''}</div>${ctx.isRecovery()?'<div class="notice recovery-alert">Os dados salvos não puderam ser lidos. Use Backup e dados para exportar o arquivo original e restaurar uma cópia válida.</div>':''}${body}</main></div></div>`;
}
function overview(d){const today=clinicNow().date,paid=d.orders.filter(o=>['paid','shipped','delivered'].includes(o.status)),upcoming=d.bookings.filter(b=>b.date>=today&&b.status==='confirmed').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5),low=d.products.filter(p=>p.active&&p.stock<=3),todayBookings=d.bookings.filter(b=>b.date===today&&b.status!=='cancelled');
 return `<div class="notice">Esta é sua área de gestão. Textos, preços e estoque iniciais são exemplos editáveis. Antes de compartilhar o site, cadastre seus dados em <a href="#/admin/content"><strong>Conteúdo e marca</strong></a>.</div><div class="stats">${[[icon('calendar'),'Atendimentos hoje',todayBookings.length,'Agenda de '+dateLabel(today)],[icon('box'),'Pedidos pendentes',d.orders.filter(o=>o.status==='pending').length,'Aguardando confirmação de pagamento'],[icon('bag'),'Vendas confirmadas',money(paid.reduce((n,o)=>n+o.total,0)),'Pedidos pagos, enviados e entregues'],[icon('users'),'Clientes',customerList(d).length,'Contatos únicos por e-mail']].map(([ico,label,value,sub])=>`<div class="stat-card"><div class="stat-label">${label}${ico}</div><strong>${value}</strong><p>${e(sub)}</p></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Próximos cuidados</h2><a class="text-btn" href="#/admin/agenda">Ver agenda</a></div>${upcoming.length?upcoming.map(b=>`<button class="appointment-row" data-booking="${e(b.id)}"><div class="date-square"><strong>${Number(b.date.slice(-2))}</strong><small>${dateLabel(b.date).split(' ')[2]||b.date.slice(5,7)}</small></div><div class="row-main"><strong>${e(b.customer.name)}</strong><p>${e(b.serviceTitle)}</p></div><div class="row-end"><strong>${b.time}</strong><small>${b.duration} min</small></div></button>`).join(''):empty('Seus próximos agendamentos aparecerão aqui.')}</section><section class="panel"><div class="panel-head"><h2>Pedidos recentes</h2><a class="text-btn" href="#/admin/orders">Ver pedidos</a></div>${d.orders.length?d.orders.slice(0,5).map(o=>`<button class="appointment-row" data-order="${e(o.id)}"><div class="small-icon">${icon('bag')}</div><div class="row-main"><strong>${e(o.customer.name)}</strong><p>#${e(o.id.slice(0,8))} · ${o.items.reduce((n,i)=>n+i.quantity,0)} item(ns)</p></div><div class="row-end"><strong>${money(o.total)}</strong>${status(o.status)}</div></button>`).join(''):empty('Ainda não há pedidos. Sua loja está pronta para receber o primeiro.','bag')}</section></div>${low.length?`<section class="panel spacer"><div class="panel-head"><h2>Estoque para acompanhar</h2><a class="text-btn" href="#/admin/products">Gerenciar produtos</a></div>${low.map(p=>`<div class="appointment-row"><div class="row-main"><strong>${e(p.title)}</strong><p>Restam ${p.stock} unidades</p></div><button class="btn secondary small" data-edit="products" data-id="${e(p.id)}">Atualizar</button></div>`).join('')}</section>`:''}<div class="quick-cards"><a href="#/admin/content">${icon('edit')}<div><strong>Um site com sua identidade</strong><p>Personalize fotos, textos e contatos.</p></div></a><a href="#/admin/availability">${icon('clock')}<div><strong>Sua agenda, seu ritmo</strong><p>Organize dias e horários disponíveis.</p></div></a><a href="#/admin/backup">${icon('download')}<div><strong>Seus dados por perto</strong><p>Exporte uma cópia de segurança.</p></div></a></div>`;
}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function agenda(d){const list=d.bookings.filter(b=>(!filters.agendaDate||b.date===filters.agendaDate)&&(filters.agendaStatus==='all'||b.status===filters.agendaStatus)&&(filters.agendaSource==='all'||b.source===filters.agendaSource)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="filter-bar">${field('agenda-date','Data',filters.agendaDate,'date')}${selectField('agenda-status','Status',[['all','Todos'],['confirmed','Confirmado'],['completed','Concluído'],['cancelled','Cancelado']],filters.agendaStatus)}${selectField('agenda-source','Origem',[['all','Todas'],['online','Site'],['whatsapp','WhatsApp']],filters.agendaSource)}<button class="btn secondary small" data-clear-agenda>Limpar filtros</button></div><section class="panel">${list.length?table(['Data e horário','Cliente','Tratamento','Origem','Status',''],list.map(b=>`<tr><td><strong>${dateLabel(b.date)}</strong><small>${b.time} · ${b.duration} min</small></td><td><strong>${e(b.customer.name)}</strong><small>${e(b.customer.phone)}</small></td><td>${e(b.serviceTitle)}<small>${money(b.price)}</small></td><td><span class="source">${b.source==='whatsapp'?icon('whatsapp'):'Site'}${b.source==='whatsapp'?'WhatsApp':''}</span></td><td>${status(b.status)}</td><td><button class="btn secondary small" data-booking="${e(b.id)}">Detalhes</button></td></tr>`)):empty('Nenhum agendamento encontrado para estes filtros.')}</section><p class="hint spacer">Horários de Brasília. Agendamentos cancelados liberam o período para novas reservas.</p>`;}
function availability(d){const a=d.availability,days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];return `<section class="panel"><div class="panel-head"><h2>Horários semanais</h2><span class="status">Brasília · UTC−3</span></div><form id="weekly-form" class="panel-body"><p class="hint" style="margin-bottom:24px">Informe os períodos separados por vírgula. Exemplo: <strong>09:00-12:00, 13:00-18:00</strong>. Deixe vazio nos dias em que não atende.</p>${days.map((day,i)=>`<div class="weekly-row"><label for="weekly-${i}">${day}</label><input id="weekly-${i}" name="day-${i}" value="${e(a.weekly[i].map(r=>r.join('-')).join(', '))}" placeholder="Fechado" maxlength="300" aria-describedby="weekly-help"></div>`).join('')}<p id="weekly-help" class="hint">Um tratamento só pode começar se couber inteiro no período. Agendamentos existentes são preservados quando os horários mudam.</p><div class="form-row spacer">${selectField('interval','Intervalo entre inícios disponíveis',[['15','15 minutos'],['30','30 minutos'],['60','60 minutos']],a.interval)}<div class="field" style="justify-content:end"><button class="btn primary" type="submit">Salvar horários semanais</button></div></div></form></section><section class="panel spacer"><div class="panel-head"><h2>Datas especiais e bloqueios</h2></div><div class="panel-body"><form id="override-form"><div class="form-row">${field('date','Data específica','','date','required')}${field('ranges','Períodos disponíveis','','text','maxlength="300" placeholder="09:00-12:00, 14:00-17:00"')}</div><label class="checkbox-label"><input name="blocked" type="checkbox">Bloquear o dia inteiro (férias, feriado ou pausa)</label><button class="btn primary small" type="submit">Adicionar data especial</button></form><p class="hint spacer">A data especial substitui os horários semanais daquele dia. Reservas existentes continuam registradas.</p>${Object.entries(a.overrides).sort(([a],[b])=>a.localeCompare(b)).map(([date,rs])=>`<div class="override-row"><div><strong>${dateLabel(date)}</strong><p>${rs.length?e(rs.map(r=>r.join(' – ')).join(' · ')):'Dia bloqueado'}</p></div><button class="icon-btn" data-remove-override="${date}" aria-label="Remover exceção de ${dateLabel(date)}">${icon('trash')}</button></div>`).join('')}</div></section>`;}
function catalog(d,type){const isService=type==='services',list=d[type];return `<section class="panel">${list.length?table(isService?['Tratamento','Duração','Valor','Visibilidade','Ordem','Ações']:['Produto','Categoria','Preço','Estoque','Visibilidade','Ações'],list.map((x,i)=>`<tr><td><div class="catalog-cell">${x.image?`<img src="${e(x.image)}" alt="" width="48" height="48">`:`<span class="small-icon">${icon(isService?'foot':'bag')}</span>`}<div><strong>${e(x.title)}</strong><small>${e(isService?x.category:x.description.slice(0,50))}</small></div></div></td><td>${isService?x.duration+' min':e(x.category)}</td><td>${money(x.price)}</td><td>${isService?`<span class="status ${x.active?'':'cancelled'}">${x.active?'Publicado':'Oculto'}</span>`:`<span class="${x.stock<=3?'stock-low':''}">${x.stock} un.</span>`}</td>${isService?`<td><div class="flex"><button class="icon-btn compact" data-move="-1" data-id="${e(x.id)}" ${i===0?'disabled':''} aria-label="Mover ${e(x.title)} para cima">${icon('up')}</button><button class="icon-btn compact" data-move="1" data-id="${e(x.id)}" ${i===list.length-1?'disabled':''} aria-label="Mover ${e(x.title)} para baixo">${icon('down')}</button></div></td>`:`<td><span class="status ${x.active?'':'cancelled'}">${x.active?'Publicado':'Oculto'}</span></td>`}<td><div class="flex"><button class="icon-btn compact" data-edit="${type}" data-id="${e(x.id)}" aria-label="Editar ${e(x.title)}">${icon('edit')}</button><button class="icon-btn compact" data-delete="${type}" data-id="${e(x.id)}" aria-label="Excluir ${e(x.title)}">${icon('trash')}</button></div></td></tr>`)):empty(isService?'Adicione seu primeiro tratamento.':'Adicione seu primeiro produto.',isService?'foot':'bag')}</section><p class="hint spacer">${isService?'A ordem desta lista é a mesma do site. Ocultar um tratamento mantém seu histórico de agendamentos.':'O estoque é reservado ao registrar um pedido e devolvido no cancelamento. Pedidos anteriores mantêm os valores originais.'}</p>`;}
function orders(d){const list=d.orders.filter(o=>filters.ordersStatus==='all'||o.status===filters.ordersStatus);return `<div class="filter-bar">${selectField('orders-status','Status do pedido',[['all','Todos os pedidos'],...['pending','paid','shipped','delivered','cancelled'].map(s=>[s,statusLabel[s]])],filters.ordersStatus)}<div class="filter-summary">${list.length} pedido(s) · ${money(list.filter(o=>o.status!=='cancelled').reduce((n,o)=>n+o.total,0))}</div></div><section class="panel">${list.length?table(['Pedido','Cliente','Itens','Total','Status',''],list.map(o=>`<tr><td><strong>#${e(o.id.slice(0,8))}</strong><small>${new Date(o.createdAt).toLocaleDateString('pt-BR')}</small></td><td><strong>${e(o.customer.name)}</strong><small>${e(o.customer.phone)}</small></td><td>${o.items.map(i=>`${i.quantity} × ${e(i.title)}`).join('<br>')}</td><td class="nowrap"><strong>${money(o.total)}</strong></td><td>${status(o.status)}</td><td><button class="btn secondary small" data-order="${e(o.id)}">Detalhes</button></td></tr>`)):empty('Nenhum pedido encontrado.','box')}</section>`;}
function customerList(d){const map=new Map();for(const b of d.bookings){const key=b.customer.email.toLowerCase(),c=map.get(key)||{...b.customer,bookings:[],orders:[]};c.bookings.push(b);map.set(key,c);}for(const o of d.orders){const key=o.customer.email.toLowerCase(),c=map.get(key)||{...o.customer,bookings:[],orders:[]};c.orders.push(o);map.set(key,c);}return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function customers(d){const list=customerList(d).filter(c=>`${c.name} ${c.email} ${c.phone}`.toLowerCase().includes(filters.customerQuery.toLowerCase()));return `<div class="filter-bar">${field('customer-search','Buscar cliente',filters.customerQuery,'search','placeholder="Nome, e-mail ou telefone" maxlength="100"')}</div><section class="panel">${list.length?table(['Cliente','Contato','Atendimentos','Pedidos','Vendas confirmadas',''],list.map(c=>`<tr><td><strong>${e(c.name)}</strong></td><td>${e(c.email)}<small>${e(c.phone)}</small></td><td>${c.bookings.filter(b=>b.status!=='cancelled').length}</td><td>${c.orders.length}</td><td>${money(c.orders.filter(o=>['paid','shipped','delivered'].includes(o.status)).reduce((n,o)=>n+o.total,0))}</td><td><button class="btn secondary small" data-customer="${e(c.email)}">Histórico</button></td></tr>`)):empty('Nenhum cliente encontrado.','users')}</section>`;}
const groups={
  hero:{title:'Página inicial',fields:[['announcement','Faixa do topo'],['heroEyebrow','Chamada acima do título'],['heroTitle','Título principal','area'],['heroDescription','Descrição principal','area'],['bookLabel','Botão de agendamento'],['shopLabel','Botão da loja'],['heroBadgeTitle','Título sobre a imagem'],['heroBadgeText','Texto sobre a imagem'],['benefit1','Benefício 1'],['benefit2','Benefício 2'],['benefit3','Benefício 3'],['heroImage','Imagem principal','image'],['heroImageAlt','Descrição acessível da imagem']]},
  brand:{title:'Marca e navegação',fields:[['brand','Nome da marca'],['tagline','Complemento da marca'],['accent','Cor principal','color'],['logo','Logo','image'],['navHome','Link: início'],['navServices','Link: tratamentos'],['navAbout','Link: especialista'],['navShop','Link: loja'],['navContact','Link: contato'],['footerDescription','Descrição no rodapé'],['footerCopyright','Texto dos direitos no rodapé']]},
  about:{title:'A especialista',fields:[['aboutEyebrow','Chamada da seção'],['aboutTitle','Título','area'],['specialist','Nome da especialista'],['qualification','Qualificações e experiência'],['aboutDescription','Sua história e filosofia de cuidado','area'],['aboutPill1','Destaque 1'],['aboutPill2','Destaque 2'],['aboutImage','Sua foto ou foto do consultório','image'],['aboutImageAlt','Descrição acessível da foto']]},
  services:{title:'Seção de tratamentos',fields:[['serviceEyebrow','Chamada da seção'],['serviceTitle','Título','area'],['serviceDescription','Descrição','area'],['serviceLink','Botão de cada tratamento']]},
  shop:{title:'Loja e agendamento',fields:[['shopEyebrow','Chamada da loja'],['shopTitle','Título da loja'],['shopDescription','Descrição da loja','area'],['shopButton','Botão para ver a loja'],['bookingTitle','Título do convite ao agendamento'],['bookingDescription','Descrição do convite','area']]},
  interface:{title:'Textos de interface',fields:[['heroTag','Legenda sobre a foto'],['heroReassurance','Texto abaixo dos botões'],['contactOfficeLabel','Título do endereço'],['contactHoursLabel','Título dos horários'],['contactFormTitle','Título do formulário'],['contactNameLabel','Campo: nome'],['contactEmailLabel','Campo: e-mail'],['contactMessageLabel','Campo: mensagem'],['contactConsent','Autorização de contato','area'],['contactSubmitLabel','Botão de envio'],['contactPrivacy','Aviso abaixo do formulário'],['mapTitle','Título do mapa'],['mapButton','Botão do mapa'],['socialLabel','Link do Instagram'],['adminLinkLabel','Link para o painel']]},
  contact:{title:'Contatos',fields:[['contactEyebrow','Chamada da seção'],['contactTitle','Título'],['contactDescription','Descrição','area'],['phone','WhatsApp com código do país (ex.: 5511999999999)','tel'],['email','E-mail do consultório','email'],['instagram','Instagram (@perfil ou URL)'],['address','Endereço completo','area'],['hours','Horários exibidos no contato','area']]}
};
function imageField(name,label,value){return `<div class="image-editor"><label class="field-label" for="f-${name}">${e(label)}</label><div class="image-editor-row">${value?`<img src="${e(value)}" alt="Prévia de ${e(label)}" width="100" height="90">`:`<div class="small-icon">${icon('upload')}</div>`}<div class="image-inputs">${field(name,'URL HTTPS ou caminho local',value.startsWith('data:')?'':value,'text','maxlength="2000" placeholder="https://…"')}<input type="file" name="upload-${name}" accept="image/jpeg,image/png,image/webp" aria-label="Enviar ${e(label)}"><label class="checkbox-label"><input type="checkbox" name="remove-${name}">Remover imagem atual</label></div></div><p class="hint">PNG, JPEG ou WebP até 10 MB. A imagem é otimizada e salva no servidor.</p></div>`;}
function content(d){const g=groups[contentGroup];return `<div class="content-tabs" role="group" aria-label="Seções do conteúdo">${Object.entries(groups).map(([id,g])=>`<button class="chip ${id===contentGroup?'active':''}" data-content-group="${id}" aria-pressed="${id===contentGroup}">${g.title}</button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${g.title}</h2><a class="text-btn" href="#/">Pré-visualizar site</a></div><form id="content-form" class="panel-body">${g.fields.map(([k,l,t])=>t==='image'?imageField(k,l,d.content[k]):t==='area'?area(k,l,d.content[k],'maxlength="8000"'):field(k,l,d.content[k],t||'text',`maxlength="8000" ${['email','tel'].includes(t)?'':''}`)).join('')}<div class="content-save"><p class="hint">Alterações são aplicadas ao salvar.</p><button class="btn primary" type="submit">${icon('check')} Salvar alterações</button></div></form></section>`;}
function notifications(d){return `<div class="flex" style="justify-content:space-between;margin-bottom:20px"><span class="hint">${d.notifications.filter(n=>!n.read).length} não lida(s)</span><button class="btn secondary small" data-read-all>Marcar todas como lidas</button></div><section class="panel">${d.notifications.length?d.notifications.map(n=>`<button class="notification-row ${n.read?'':'unread'}" data-notification="${e(n.id)}"><div class="small-icon">${icon(n.kind==='booking'?'calendar':n.kind==='order'?'bag':'mail')}</div><div class="row-main"><strong>${e(n.title)}</strong><p>${e(n.text)}</p><small>${new Date(n.createdAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · Aviso no painel</small></div>${n.read?'':`<span class="unread-dot" aria-label="Não lida"></span>`}</button>`).join(''):empty('Você está em dia. Os próximos avisos aparecerão aqui.','bell')}</section><p class="hint spacer">Notificações são registradas no servidor e aparecem ao atualizar o painel. E-mails e push externos precisam de um serviço conectado.</p>`;}
function messages(d){return `<section class="panel">${d.messages.length?d.messages.map(m=>`<button class="notification-row ${m.read?'':'unread'}" data-message="${e(m.id)}"><div class="small-icon">${icon('mail')}</div><div class="row-main"><strong>${e(m.name)}</strong><p>${e(m.message.slice(0,140))}</p><small>${e(m.email)} · ${new Date(m.createdAt).toLocaleDateString('pt-BR')}</small></div>${m.read?'':`<span class="unread-dot"></span>`}</button>`).join(''):empty('Nenhuma mensagem por enquanto.','mail')}</section>`;}
function backup(ctx){const d=ctx.getData();return `<div class="notice">Os dados ficam no servidor e são compartilhados entre dispositivos autorizados. Exporte backups regularmente e guarde-os com cuidado, pois podem conter dados de clientes.</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Exportar seus dados</h2>${icon('download')}</div><div class="panel-body"><p>Uma cópia inclui conteúdo, imagens enviadas, tratamentos, produtos, agenda, pedidos, clientes e mensagens.</p><div class="backup-counts">${d.services.length} tratamentos · ${d.products.length} produtos<br>${d.bookings.length} agendamentos · ${d.orders.length} pedidos</div><button class="btn primary" data-export>${icon('download')} Baixar backup JSON</button>${ctx.isRecovery()?'<button class="btn secondary spacer" data-export-raw>Baixar arquivo original para recuperação</button>':''}</div></section><section class="panel"><div class="panel-head"><h2>Restaurar um backup</h2>${icon('upload')}</div><div class="panel-body"><p>Escolha um arquivo exportado por este aplicativo. Você poderá revisar o conteúdo antes de substituir seus dados.</p><div class="field spacer"><label for="import-file">Arquivo de backup (.json)</label><input type="file" id="import-file" accept="application/json,.json"></div><p class="hint">A versão anterior fica preservada no servidor após uma alteração administrativa.</p><button class="btn secondary spacer" data-restore-previous>Restaurar cópia anterior</button></div></section></div><section class="panel spacer"><div class="panel-head"><h2>Recomeçar com os exemplos</h2></div><div class="panel-body"><p class="hint">Esta opção substitui o conteúdo e remove os registros do servidor. Exporte um backup primeiro.</p><button class="btn danger small spacer" data-reset>Restaurar exemplos iniciais</button></div></section>`;}
function parseRanges(text){if(!text.trim())return [];return text.split(',').map(x=>{const match=x.trim().match(/^(\d{2}:\d{2})\s*[-–]\s*(\d{2}:\d{2})$/);if(!match)throw new Error('Use o formato 09:00-12:00, 13:00-18:00.');return [match[1],match[2]];}).sort((a,b)=>a[0].localeCompare(b[0]));}
async function act(fn){try{await fn();}catch(err){toast(err.message);}}
function confirmAction(title,text,fn,label='Confirmar'){const el=modal(title,`<p>${e(text)}</p>`,`<button class="btn secondary" data-cancel>Voltar</button><button class="btn danger" data-confirm>${e(label)}</button>`);el.querySelector('[data-cancel]').onclick=()=>el.close();el.querySelector('[data-confirm]').onclick=async()=>{const b=el.querySelector('[data-confirm]');b.disabled=true;try{await fn();el.close();}catch(err){error(err);b.disabled=false;}};}
function editItem(ctx,type,id){const old=ctx.getData()[type].find(x=>x.id===id),isService=type==='services',x=old||{title:'',description:'',category:'',price:0,duration:60,stock:0,image:'',active:true};const el=modal(`${old?'Editar':'Novo'} ${isService?'tratamento':'produto'}`,`<form id="item-form">${field('title','Título',x.title,'text','required maxlength="160"')}${area('description','Descrição',x.description,'required maxlength="3000"')}${field('category','Categoria',x.category,'text','maxlength="100"')}<div class="form-row">${field('price','Preço (R$)',x.price,'number','required min="0" max="100000" step="0.01"')}${isService?field('duration','Duração (minutos)',x.duration,'number','required min="15" max="480" step="15"'):field('stock','Quantidade em estoque',x.stock,'number','required min="0" max="100000" step="1"')}</div>${imageField('image','Foto',x.image)}<label class="checkbox-label"><input name="active" type="checkbox" ${x.active?'checked':''}>Publicado no site</label><div class="content-save"><button type="button" class="btn secondary" data-cancel>Voltar</button><button type="submit" class="btn primary">Salvar ${isService?'tratamento':'produto'}</button></div></form>`);el.querySelector('[data-cancel]').onclick=()=>el.close();submit(el.querySelector('form'),async(v,form)=>{let image=x.image;if(v['remove-image']==='on')image='';else {const f=form.querySelector('[name=upload-image]').files[0];if(f)image=await uploadImage(f);else if(v.image.trim())image=v.image.trim();}if(!validImage(image))throw new Error('Imagem inválida. Use uma URL HTTPS ou envie um arquivo.');await transaction(d=>{const next={id:old?.id||uid(),title:v.title.trim(),description:v.description.trim(),category:v.category.trim(),price:Number(v.price),image,active:v.active==='on',...(isService?{duration:Number(v.duration)}:{stock:Number(v.stock)})};const i=d[type].findIndex(x=>x.id===next.id);if(old&&i<0)throw new Error('Este item foi removido em outra aba.');if(i>=0){if(!isService&&d[type][i].stock!==old.stock){if(next.stock===old.stock)next.stock=d[type][i].stock;else throw new Error('O estoque mudou enquanto você editava. Abra o produto novamente para atualizar.');}d[type][i]=next;}else d[type].push(next);});el.close();toast('Alterações salvas.');});}
function bookingDetail(ctx,id){const b=ctx.getData().bookings.find(x=>x.id===id);if(!b)return toast('Agendamento não encontrado.');const wa=whatsappLink(b.customer.phone.replace(/\D/g,"").length<=11?'55'+b.customer.phone.replace(/\D/g,''):b.customer.phone,`Olá, ${b.customer.name}! Seu cuidado ${b.serviceTitle} está agendado para ${dateLabel(b.date)} às ${b.time}.`);const el=modal('Detalhes do agendamento',`${status(b.status)}<div class="booking-summary"><strong>${e(b.serviceTitle)}</strong><p>${dateLabel(b.date,true)} · ${b.time} (Brasília)</p><p>${b.duration} min · ${money(b.price)}</p></div><div class="detail-grid"><div><label>Cliente</label><strong>${e(b.customer.name)}</strong></div><div><label>Origem</label><strong>${b.source==='whatsapp'?'WhatsApp':'Agendamento online'}</strong></div><div><label>Telefone</label><strong>${e(b.customer.phone)}</strong></div><div><label>E-mail</label><strong>${e(b.customer.email)}</strong></div></div><p class="hint spacer">Observações</p><p class="preline">${e(b.customer.notes||'Nenhuma observação.')}</p><div class="flex spacer">${wa?`<a class="btn secondary small" href="${e(wa)}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')} Falar com cliente</a>`:''}<button class="btn secondary small" data-receipt>${icon('download')} Comprovante</button></div>`,`<button class="btn danger small" data-cancel-booking ${b.status==='cancelled'?'disabled':''}>Cancelar</button><div class="flex"><button class="btn secondary small" data-reschedule ${b.status!=='confirmed'?'disabled':''}>Reagendar</button><button class="btn primary small" data-complete ${b.status!=='confirmed'?'disabled':''}>Marcar concluído</button></div>`);el.querySelector('[data-receipt]').onclick=()=>download(`agendamento-${b.id.slice(0,8)}.txt`,bookingText(b),'text/plain;charset=utf-8');el.querySelector('[data-cancel-booking]').onclick=()=>confirmAction('Cancelar agendamento?',`O horário de ${b.customer.name} será liberado para novas reservas.`,async()=>{await changeBooking(id,'cancelled');toast('Agendamento cancelado.');},'Cancelar agendamento');el.querySelector('[data-complete]').onclick=()=>act(async()=>{await changeBooking(id,'completed');el.close();toast('Atendimento concluído.');});el.querySelector('[data-reschedule]').onclick=()=>reschedule(ctx,b);}
function reschedule(ctx,b){const el=modal('Reagendar atendimento',`<form id="reschedule-form"><p class="hint">${e(b.serviceTitle)} · ${b.duration} min · ${e(b.customer.name)}</p>${field('date','Nova data',b.date,'date','required')}<div id="reschedule-times"></div><button type="submit" class="btn primary full spacer">Salvar novo horário</button></form>`);const date=el.querySelector('[name=date]');function update(){const times=slots(ctx.getData(),b.serviceId,date.value,b.id);el.querySelector('#reschedule-times').innerHTML=times.length?selectField('time','Novo horário',times.map(t=>[t,t]),b.time,'required'):empty('Não há horários disponíveis nesta data.');el.querySelector('[type=submit]').disabled=!times.length;}date.onchange=update;update();submit(el.querySelector('form'),async v=>{await transaction(d=>{const current=d.bookings.find(x=>x.id===b.id),s=d.services.find(x=>x.id===b.serviceId);if(!current||current.status!=='confirmed'||!s||s.duration!==b.duration)throw new Error('O agendamento ou tratamento mudou. Abra os detalhes novamente.');if(!slots(d,b.serviceId,v.date,b.id).includes(v.time))throw new Error('Horário indisponível. Escolha outro.');current.date=v.date;current.time=v.time;});el.close();toast('Agendamento atualizado.');});}
function orderDetail(ctx,id){const o=ctx.getData().orders.find(x=>x.id===id);if(!o)return toast('Pedido não encontrado.');const wa=whatsappLink(o.customer.phone.replace(/\D/g,'').length<=11?'55'+o.customer.phone.replace(/\D/g,''):o.customer.phone,`Olá, ${o.customer.name}! Vamos conversar sobre o pedido #${o.id.slice(0,8)} na BABE?`);const el=modal(`Pedido #${o.id.slice(0,8)}`,`${status(o.status)}<div class="detail-grid spacer"><div><label>Cliente</label><strong>${e(o.customer.name)}</strong></div><div><label>Telefone</label><strong>${e(o.customer.phone)}</strong></div><div><label>E-mail</label><strong>${e(o.customer.email)}</strong></div><div><label>Recebimento</label><strong>${o.delivery==='pickup'?'Retirada no consultório':'Entrega a combinar'}</strong></div></div><p class="spacer preline">${e(o.address)}</p><div class="order-items">${o.items.map(i=>`<div><span>${i.quantity} × ${e(i.title)}</span><strong>${money(i.price*i.quantity)}</strong></div>`).join('')}<div class="total-row"><strong>Total</strong><strong>${money(o.total)}</strong></div></div><p class="hint">Observações</p><p class="preline">${e(o.customer.notes||'Nenhuma observação.')}</p><form id="order-status-form" class="spacer"><div class="form-row">${selectField('status','Atualizar status',['pending','paid','shipped','delivered','cancelled'].map(s=>[s,statusLabel[s]]),o.status,o.status==='cancelled'?'disabled':'')}<div class="field" style="justify-content:end"><button class="btn primary" type="submit" ${o.status==='cancelled'?'disabled':''}>Salvar status</button></div></div></form><div class="history"><h3>Histórico do pedido</h3>${o.history.map(h=>`<p><span>${e(statusLabel[h.status]||h.status)}</span><small>${new Date(h.at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></p>`).join('')}</div>`,`<button class="text-btn" data-receipt>${icon('download')} Comprovante</button>${wa?`<a class="btn secondary small" href="${e(wa)}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')} Falar com cliente</a>`:''}`);el.querySelector('[data-receipt]').onclick=()=>download(`pedido-${id.slice(0,8)}.txt`,orderText(o),'text/plain;charset=utf-8');submit(el.querySelector('form'),async v=>{if(v.status==='cancelled'){confirmAction('Cancelar pedido?','As unidades reservadas serão devolvidas ao estoque. O registro e seu histórico serão mantidos.',async()=>{await changeOrder(id,'cancelled');toast('Pedido cancelado e estoque atualizado.');},'Cancelar pedido');return;}await changeOrder(id,v.status);orderDetail(ctx,id);toast('Status do pedido atualizado.');});}
function customerDetail(ctx,email){const c=customerList(ctx.getData()).find(x=>x.email===email);if(!c)return;modal(c.name,`<p>${e(c.email)} · ${e(c.phone)}</p><h3 class="detail-title">Agendamentos</h3>${c.bookings.map(b=>`<div class="appointment-row"><div class="row-main"><strong>${e(b.serviceTitle)}</strong><p>${dateLabel(b.date)} · ${b.time}</p></div>${status(b.status)}</div>`).join('')||empty('Nenhum agendamento.')}<h3 class="detail-title">Pedidos</h3>${c.orders.map(o=>`<div class="appointment-row"><div class="row-main"><strong>#${e(o.id.slice(0,8))} · ${money(o.total)}</strong><p>${o.items.map(i=>`${i.quantity} × ${e(i.title)}`).join(', ')}</p></div>${status(o.status)}</div>`).join('')||empty('Nenhum pedido.','bag')}`);}
function restorePrompt(ctx,d,label='Importar backup'){validateState(d);const el=modal(label,`<p>Este arquivo contém:</p><div class="booking-summary">${d.services.length} tratamentos · ${d.products.length} produtos<br>${d.bookings.length} agendamentos · ${d.orders.length} pedidos</div><p class="hint">Os dados atuais serão substituídos. Exporte um backup antes de continuar.</p><form id="restore-form" class="spacer">${field('confirm','Digite RESTAURAR para confirmar','','text','required pattern="RESTAURAR" autocomplete="off"')}<button type="submit" class="btn danger full">Restaurar dados</button></form>`);submit(el.querySelector('form'),async()=>{await replaceData(d);ctx.setRecovery(false);el.close();toast('Dados restaurados.');});}
export function bindAdmin(ctx){const root=document.getElementById('app'),tab=currentTab();root.querySelectorAll('[data-manual]').forEach(b=>b.onclick=()=>ctx.booking('',true));root.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>editItem(ctx,b.dataset.new));root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editItem(ctx,b.dataset.edit,b.dataset.id));root.querySelectorAll('[data-booking]').forEach(b=>b.onclick=()=>bookingDetail(ctx,b.dataset.booking));root.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderDetail(ctx,b.dataset.order));root.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>customerDetail(ctx,b.dataset.customer));
  root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const type=b.dataset.delete,item=ctx.getData()[type].find(x=>x.id===b.dataset.id);confirmAction('Excluir '+(type==='services'?'tratamento?':'produto?'),`${item.title} será removido do catálogo. O histórico de agendamentos e pedidos será mantido.`,async()=>{await transaction(d=>{d[type]=d[type].filter(x=>x.id!==b.dataset.id);});toast('Item removido.');},'Excluir');});
  root.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>act(()=>transaction(d=>{const i=d.services.findIndex(s=>s.id===b.dataset.id),j=i+Number(b.dataset.move);if(i>=0&&j>=0&&j<d.services.length)[d.services[i],d.services[j]]=[d.services[j],d.services[i]];})));
  if(tab==='agenda'){for(const [name,key]of [['agenda-date','agendaDate'],['agenda-status','agendaStatus'],['agenda-source','agendaSource']])root.querySelector(`[name=${name}]`).onchange=ev=>{filters[key]=ev.target.value;ctx.render();};root.querySelector('[data-clear-agenda]').onclick=()=>{filters.agendaDate='';filters.agendaStatus='all';filters.agendaSource='all';ctx.render();};}
  if(tab==='orders')root.querySelector('[name=orders-status]').onchange=ev=>{filters.ordersStatus=ev.target.value;ctx.render();};if(tab==='customers')root.querySelector('[name=customer-search]').onchange=ev=>{filters.customerQuery=ev.target.value;ctx.render();};
  if(tab==='availability'){submit(root.querySelector('#weekly-form'),async v=>{const weekly=Object.fromEntries(Array.from({length:7},(_,i)=>[i,parseRanges(v['day-'+i])]));await transaction(d=>{d.availability.weekly=weekly;d.availability.interval=Number(v.interval);});toast('Horários semanais atualizados.');});submit(root.querySelector('#override-form'),async v=>{if(!validDate(v.date))throw new Error('Escolha uma data válida.');const ranges=v.blocked==='on'?[]:parseRanges(v.ranges);if(v.blocked!=='on'&&!ranges.length)throw new Error('Informe um período ou marque o bloqueio do dia.');await transaction(d=>{d.availability.overrides[v.date]=ranges;});toast('Data especial salva.');});root.querySelectorAll('[data-remove-override]').forEach(b=>b.onclick=()=>act(()=>transaction(d=>{delete d.availability.overrides[b.dataset.removeOverride];})));}
  if(tab==='content'){root.querySelectorAll('[data-content-group]').forEach(b=>b.onclick=()=>{contentGroup=b.dataset.contentGroup;ctx.render();});submit(root.querySelector('#content-form'),async(v,form)=>{const changed={};for(const[k,l,t]of groups[contentGroup].fields){if(t==='image'){const file=form.querySelector(`[name=upload-${k}]`).files[0];if(v['remove-'+k]==='on')changed[k]='';else if(file)changed[k]=await uploadImage(file);else if(v[k].trim()||!ctx.getData().content[k].startsWith('data:'))changed[k]=v[k].trim();}else changed[k]=v[k];}if(changed.phone){changed.phone=changed.phone.replace(/\D/g,'');if(!/^\d{10,15}$/.test(changed.phone))throw new Error('Cadastre o WhatsApp com o código do país e DDD.');}await transaction(d=>{Object.assign(d.content,changed);});toast('Seu conteúdo foi atualizado.');});}
  if(tab==='notifications'){root.querySelector('[data-read-all]').onclick=()=>act(()=>transaction(d=>{d.notifications.forEach(n=>n.read=true);}));root.querySelectorAll('[data-notification]').forEach(b=>b.onclick=()=>act(async()=>{const n=ctx.getData().notifications.find(x=>x.id===b.dataset.notification);await transaction(d=>{d.notifications.find(x=>x.id===n.id).read=true;});if(n.kind==='booking')bookingDetail(ctx,n.ref);else if(n.kind==='order')orderDetail(ctx,n.ref);else showMessage(ctx,n.ref);}));}
  root.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>act(()=>showMessage(ctx,b.dataset.message)));
  if(tab==='backup'){root.querySelector('[data-export]').onclick=()=>download(`babe-backup-${clinicNow().date}.json`,JSON.stringify(ctx.getData(),null,2));root.querySelector('[data-export-raw]')?.addEventListener('click',()=>download('babe-dados-originais.json',localStorage.getItem(KEY)||''));root.querySelector('#import-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>6*1024*1024)throw new Error('Escolha um backup de até 6 MB.');restorePrompt(ctx,JSON.parse(await file.text()));}catch(err){toast('Não foi possível importar: '+err.message);ev.target.value='';}};root.querySelector('[data-restore-previous]').onclick=()=>act(async()=>{restorePrompt(ctx,await previousBackup(),'Restaurar cópia anterior');});root.querySelector('[data-reset]').onclick=()=>restorePrompt(ctx,seed(),'Restaurar exemplos iniciais');}
}
async function showMessage(ctx,id){const m=ctx.getData().messages.find(x=>x.id===id);if(!m)return toast('Mensagem não encontrada.');await transaction(d=>{d.messages.find(x=>x.id===id).read=true;});modal('Mensagem de '+m.name,`<p class="hint">${e(m.email)} · ${new Date(m.createdAt).toLocaleString('pt-BR')}</p><p class="preline spacer">${e(m.message)}</p>`,`<span></span><a class="btn primary" href="mailto:${e(m.email)}?subject=${encodeURIComponent('Sua mensagem para a BABE')}">${icon('mail')} Responder por e-mail</a>`);}
